/* Pochita CP949 codec map. Mapping generated from Python's built-in cp949 codec. */
(function(){
  const encoded = "";
  const raw = Uint8Array.from(atob(encoded), c => c.charCodeAt(0));
  const encodeMap = new Map(), pairDecode = new Map(), singleDecode = new Map();
  for (let i = 0; i + 3 < raw.length; i += 4) {
    const cp = raw[i] | (raw[i + 1] << 8);
    const packed = raw[i + 2] | (raw[i + 3] << 8);
    encodeMap.set(cp, packed);
    if (packed < 0x100) singleDecode.set(packed, String.fromCharCode(cp));
    else pairDecode.set(packed, String.fromCharCode(cp));
  }
  function encode(text) {
    const out = [];
    for (const ch of String(text)) {
      const cp = ch.codePointAt(0);
      if (cp < 0x80) { out.push(cp); continue; }
      const packed = encodeMap.get(cp);
      if (packed === undefined) throw new Error(`Character ${JSON.stringify(ch)} (U+${cp.toString(16).toUpperCase()}) cannot be encoded in CP949.`);
      if (packed < 0x100) out.push(packed);
      else out.push((packed >> 8) & 255, packed & 255);
    }
    return Uint8Array.from(out);
  }
  function decode(input) {
    const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
    let out = '';
    for (let i=0; i<bytes.length;) {
      const first=bytes[i];
      if (first < 0x80) { out += String.fromCharCode(first); i++; continue; }
      if (i+1 < bytes.length) {
        const pair=(first<<8)|bytes[i+1], found=pairDecode.get(pair);
        if (found !== undefined) { out += found; i+=2; continue; }
      }
      const single=singleDecode.get(first);
      if (single !== undefined) { out += single; i++; continue; }
      throw new Error(`Invalid CP949 byte sequence at byte offset ${i}.`);
    }
    return out;
  }
  window.PochitaCP949 = { encode, decode, mappingCount: encodeMap.size };
})();
